"use client";

import { useEffect, useRef, useState } from "react";
import type { CSSProperties, HTMLAttributes } from "react";

export interface NoiseTransferProps extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** "out" sends rings from the center to the edge (uploading, sending); "in" brings them from the edge to the center (downloading, receiving). */
  direction?: "out" | "in";
  /** Number of concentric rings (1–5). */
  lines?: number;
  /** Stroke width of each ring in px. */
  lineWidth?: number;
  /** Furthest the outer ring is pushed in or out by the noise, in px. Inner rings move proportionally less. */
  amplitude?: number;
  /** How many bumps run around a ring. Low values give broad, soft swells; high values give tighter ripples. */
  frequency?: number;
  /** How fast the noise drifts over time. The animation keeps its own pace, set by `duration`. */
  speed?: number;
  /** Seconds for one ring to travel from the center to the edge (or back, going in). */
  duration?: number;
  /** How differently neighboring rings move. 0 keeps them in lockstep; higher lets each ring wander on its own. */
  spread?: number;
  /** Gap between neighboring rings in px. */
  lineSpacing?: number;
  /** Canvas size in px (the loader is square). */
  size?: number;
  /** Line color, any CSS color. */
  color?: string;
  /** Opacity of the innermost ring (0–1). The outer ring is always 1. */
  minOpacity?: number;
  /** Coast to a stop on the current frame. Turning it back off eases the animation back up to speed. */
  paused?: boolean;
  /** Accessible name; the wrapper is role="status". */
  label?: string;
}

function scene() {
  const motion = soloNoise("transfer");
  return noiseScene<NoiseSettings, never>(() => motion);
}

export function NoiseTransfer({
  direction = "out",
  lines = 4,
  lineWidth = 1,
  amplitude = 8,
  frequency = 0.8,
  speed = 0.35,
  duration = 2.4,
  spread = 0.12,
  lineSpacing = 3,
  size = 160,
  color = "#e4e4e7",
  minOpacity = 0.35,
  paused = false,
  label = "Uploading",
  ...rest
}: NoiseTransferProps) {
  const settings: NoiseSettings = { direction, lines, lineWidth, amplitude, frequency, speed, duration, spread, lineSpacing, size, color, minOpacity, paused };
  return <LoaderCanvas settings={settings} targets={noiseTargets} settle={noiseSettle} scene={scene} label={label} {...rest} />;
}

export default NoiseTransfer;

/**
 * Glide times are a spring's time constant, not a duration: a glide is about 90% of the way to its target
 * after twice its time, so `SETTLE` reads as a ~240ms change.
 */

/** Seconds (roughly) a changed prop takes to glide to its new value: size, spacing, timing and the like. */
const SETTLE = 0.12;

/** Color and opacity: faster, since nothing moves (~150ms). */
const FADE_SETTLE = 0.075;

/** Changing animation: one motion blending into the next (~300ms). */
const BLEND_SETTLE = 0.15;

/** Pausing: seconds (roughly) the animation takes to coast to a stop (~300ms). */
const STOP_SETTLE = 0.15;

/** Resuming: seconds (roughly) the animation takes to get back up to speed (~400ms). */
const START_SETTLE = 0.2;

/** A value that glides toward its target on a critically damped spring: no jump, no overshoot. */
type Glide = { value: number; velocity: number; target: number };

function glide(value: number): Glide {
  return { value, velocity: 0, target: value };
}

function snap(g: Glide) {
  g.value = g.target;
  g.velocity = 0;
}

/** Moves `g` toward its target. Returns false once it has arrived and is at rest. */
function stepGlide(g: Glide, dt: number, time: number) {
  if (g.value === g.target && g.velocity === 0) return false;
  const omega = 2 / time;
  const x = omega * dt;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  const change = g.value - g.target;
  const temp = (g.velocity + omega * change) * dt;
  g.velocity = (g.velocity - omega * temp) * decay;
  g.value = g.target + (change + temp) * decay;
  if (Math.abs(g.value - g.target) < 1e-3 && Math.abs(g.velocity) < 1e-3) snap(g);
  return true;
}

/** The glided value of every target, plus the canvas `size` and the pause `rate` (0 paused, 1 running). */
type Values<K extends string> = Record<K | "size" | "rate", number>;

/** What a scene sees each frame. `layers` holds every shape on screen; more than one while a change cross-fades. */
interface Frame<S, K extends string, L> {
  settings: S;
  v: Values<K>;
  layers: { shape: L; fade: number }[];
  size: number;
  /** The viewer asked for reduced motion: the clock holds still, so a scene that ends somewhere should jump there. */
  reduced: boolean;
}

interface Scene<S, K extends string, L> {
  /** Moves the scene's own clock on by `dt` seconds. Scale by `v.rate` so pausing coasts to a stop. */
  advance?(dt: number, frame: Frame<S, K, L>): void;
  /** Paints one frame onto a cleared canvas, already scaled to `size` px. */
  draw(ctx: CanvasRenderingContext2D, frame: Frame<S, K, L>): void;
}

interface LoaderCanvasProps<S extends { size: number; paused: boolean }, K extends string, L>
  extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** The latest props. Read by `targets` and `shape` on every render, and by the scene every frame. */
  settings: S;
  /** Every number the scene reads, as the latest settings want it. Each glides to its new value. */
  targets: (s: NoInfer<S>) => Record<K, number>;
  /**
   * Geometry rebuilt when its key changes. The old shape's fade glides to 0 while the new one's glides to 1:
   * a plain cross-fade, unless `morph` links the two so the scene can move one into the other.
   */
  shape?: {
    key: (s: NoInfer<S>) => string;
    build: (s: NoInfer<S>) => L;
    /** Called when `to` replaces `from`, whose fade is `fade` at that moment. */
    morph?: (from: L, to: L, fade: number) => void;
    /** Seconds (roughly) a shape change takes. Defaults to `BLEND_SETTLE`. */
    settle?: number;
  };
  /** Seconds (roughly) each target takes to glide to a new value, by key. Unlisted keys take `SETTLE`. */
  settle?: Partial<Record<NoInfer<K> | "size", number>>;
  /** Seconds (roughly) pausing takes to coast to a stop, and resuming to get back up to speed. */
  pause?: { stop: number; start: number };
  /** Called once on mount; the returned scene keeps its own clock between frames. */
  scene: () => Scene<NoInfer<S>, K, L>;
  label: string;
}

/**
 * A square canvas that runs a scene: props glide instead of jumping, pausing coasts, shape changes
 * cross-fade or morph, reduced motion holds still, and the loop sleeps once nothing is moving.
 */
function LoaderCanvas<S extends { size: number; paused: boolean }, K extends string, L>({
  settings,
  targets,
  shape,
  settle,
  pause,
  scene,
  label,
  className,
  style,
  ...rest
}: LoaderCanvasProps<S, K, L>) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Only the first size reaches the DOM through React; after that the loop glides it.
  const [initialSize] = useState(settings.size);
  const latest = useRef({ settings, targets, shape, settle, pause, scene });
  const wakeRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    latest.current = { settings, targets, shape, settle, pause, scene };
    wakeRef.current?.();
  });

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!wrapper || !canvas || !ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const { settings: first, shape: shapeOf, scene: makeScene } = latest.current;
    const sceneNow = makeScene();
    const glides = {} as Record<string, Glide>;
    const v = {} as Values<K>;
    let shapes = shapeOf ? [{ key: shapeOf.key(first), shape: shapeOf.build(first), fade: glide(1) }] : [];
    const frameInfo: Frame<S, K, L> = { settings: first, v, layers: [], size: 1, reduced: reduceMotion.matches };
    let shownSize = -1;
    let frame = 0;
    let last = 0;
    // Off screen or in a hidden tab, the loop sleeps; it picks up where it left off once seen again.
    // Starts asleep: the observer's first report wakes it, so a page of loaders only paints the ones in view.
    let onScreen = false;
    const visible = () => onScreen && document.visibilityState === "visible";

    const targetsNow = () => {
      const { settings: s, targets } = latest.current;
      return { ...targets(s), size: s.size, rate: s.paused ? 0 : 1 } as Record<string, number>;
    };
    for (const [k, value] of Object.entries(targetsNow())) glides[k] = glide(value);

    /** Refreshes what the scene reads from the glides and shapes. */
    const read = () => {
      for (const k in glides) (v as Record<string, number>)[k] = glides[k].value;
      frameInfo.settings = latest.current.settings;
      frameInfo.layers = shapes.map(({ shape, fade }) => ({ shape, fade: fade.value }));
      frameInfo.size = Math.max(1, v.size);
      frameInfo.reduced = reduceMotion.matches;
    };

    const sync = () => {
      const { settings: s, shape: shapeOf } = latest.current;
      for (const [k, value] of Object.entries(targetsNow())) glides[k].target = value;
      if (shapeOf) {
        const key = shapeOf.key(s);
        if (key !== shapes[shapes.length - 1].key) {
          for (const shape of shapes) shape.fade.target = 0;
          const fade = glide(0);
          fade.target = 1;
          const prev = shapes[shapes.length - 1];
          const next = { key, shape: shapeOf.build(s), fade };
          shapeOf.morph?.(prev.shape, next.shape, prev.fade.value);
          shapes.push(next);
        }
      }
      // Reduced motion: hold still and apply changes at once.
      if (reduceMotion.matches) {
        glides.rate.target = 0;
        for (const g of Object.values(glides)) snap(g);
        for (const shape of shapes) snap(shape.fade);
      }
    };

    const draw = () => {
      read();
      const size = frameInfo.size;
      if (size !== shownSize) {
        shownSize = size;
        wrapper.style.width = wrapper.style.height = `${size}px`;
        canvas.style.width = canvas.style.height = `${size}px`;
        const px = Math.round(size * dpr);
        if (canvas.width !== px) canvas.width = canvas.height = px;
      }
      ctx.setTransform(canvas.width / size, 0, 0, canvas.width / size, 0, 0);
      ctx.clearRect(0, 0, size, size);
      sceneNow.draw(ctx, frameInfo);
      ctx.globalAlpha = 1;
    };

    const tick = (now: number) => {
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
      last = now;
      let moving = false;
      const times: Partial<Record<string, number>> = latest.current.settle ?? {};
      const pauseTimes = latest.current.pause;
      for (const [k, g] of Object.entries(glides)) {
        // Stopping and starting take their own times; every other target its own, else `SETTLE`.
        const time =
          k === "rate"
            ? g.target > 0
              ? (pauseTimes?.start ?? START_SETTLE)
              : (pauseTimes?.stop ?? STOP_SETTLE)
            : (times[k] ?? SETTLE);
        if (stepGlide(g, dt, time)) moving = true;
      }
      const shapeSettle = latest.current.shape?.settle ?? BLEND_SETTLE;
      for (const shape of shapes) if (stepGlide(shape.fade, dt, shapeSettle)) moving = true;
      shapes = shapes.filter((shape) => shape.fade.target > 0 || shape.fade.value > 0);

      if (sceneNow.advance) {
        read();
        sceneNow.advance(dt, frameInfo);
      }
      draw();
      // Sleep once everything has settled and the animation is paused, or nobody can see it.
      frame = visible() && (moving || glides.rate.value > 0) ? requestAnimationFrame(tick) : 0;
    };

    const wake = () => {
      sync();
      if (frame || !visible()) return;
      last = 0;
      frame = requestAnimationFrame(tick);
    };

    const sleepOrWake = () => {
      if (visible()) wake();
      else {
        cancelAnimationFrame(frame);
        frame = 0;
      }
    };
    const observer = new IntersectionObserver(
      (entries) => {
        onScreen = entries[entries.length - 1].isIntersecting;
        sleepOrWake();
      },
      { rootMargin: "64px" },
    );
    observer.observe(wrapper);

    wakeRef.current = wake;
    reduceMotion.addEventListener("change", wake);
    document.addEventListener("visibilitychange", sleepOrWake);
    sync();
    return () => {
      cancelAnimationFrame(frame);
      wakeRef.current = null;
      observer.disconnect();
      reduceMotion.removeEventListener("change", wake);
      document.removeEventListener("visibilitychange", sleepOrWake);
    };
  }, []);

  const wrapperStyle: CSSProperties = { width: initialSize, height: initialSize, ...style };

  return (
    <div ref={wrapperRef} role="status" aria-label={label} className={className} style={wrapperStyle} {...rest}>
      <canvas ref={canvasRef} style={{ width: initialSize, height: initialSize, display: "block" }} />
    </div>
  );
}

let probe: CanvasRenderingContext2D | null = null;

/** Resolves any CSS color to sRGB [r, g, b, a] by painting it into one pixel, so it can be blended. */
function parseColor(color: string): [number, number, number, number] {
  probe ??= document.createElement("canvas").getContext("2d", { willReadFrequently: true });
  if (!probe) return [228, 228, 231, 1];
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = "#000"; // An invalid color leaves fillStyle as it was, so start from a known one.
  probe.fillStyle = color;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = probe.getImageData(0, 0, 1, 1).data;
  return [r, g, b, a / 255];
}

/** A CSS color as glide targets, so a color change blends instead of jumping. */
function colorTargets(color: string) {
  const [red, green, blue, alpha] = parseColor(color);
  return { red, green, blue, alpha };
}

/** The blended color as an opaque CSS color; its alpha is applied per dot through globalAlpha. */
function rgb(v: { red: number; green: number; blue: number }) {
  return `rgb(${v.red} ${v.green} ${v.blue})`;
}

function easeInOutCubic(t: number) {
  return t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
}

/** A CSS `cubic-bezier(x1, y1, x2, y2)` as a function of progress 0..1. */
function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const ax = 3 * x1 - 3 * x2 + 1;
  const bx = 3 * x2 - 6 * x1;
  const cx = 3 * x1;
  const ay = 3 * y1 - 3 * y2 + 1;
  const by = 3 * y2 - 6 * y1;
  const cy = 3 * y1;
  const curveX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const curveY = (s: number) => ((ay * s + by) * s + cy) * s;
  const slopeX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;
  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    // Newton's method finds the curve parameter whose x is `t`; bisection catches the flat spots.
    let s = t;
    for (let i = 0; i < 6; i++) {
      const dx = curveX(s) - t;
      const slope = slopeX(s);
      if (Math.abs(dx) < 1e-6) return curveY(s);
      if (Math.abs(slope) < 1e-6) break;
      s -= dx / slope;
    }
    let lo = 0;
    let hi = 1;
    s = t;
    for (let i = 0; i < 20; i++) {
      const x = curveX(s);
      if (Math.abs(x - t) < 1e-6) break;
      if (x < t) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
    }
    return curveY(s);
  };
}

/** Strong ease-out, `cubic-bezier(0.23, 1, 0.32, 1)`: for things arriving or leaving. */
const easeOut = cubicBezier(0.23, 1, 0.32, 1);

/** Strong ease-in-out, `cubic-bezier(0.77, 0, 0.175, 1)`: for things moving or morphing on screen. */
const easeInOut = cubicBezier(0.77, 0, 0.175, 1);

/** Glide key for how much of animation `A` is on screen: 1 while it is the active one, 0 when it is gone. */
type MixKey<A extends string> = `mix_${A}`;

/**
 * - `think`: the noise drifts on its own, each ring a little behind the one outside it.
 * - `respond`: a push starts at the innermost ring and travels outward, like a drop landing in water.
 * - `listen`: the wobble swells, then calms almost to circles, and swells again.
 * - `ponder`: the noise turns around the center, inner rings trailing behind, so the shape twists.
 * - `decide`: the rings close up into one line, then fan back out.
 * - `voice`: the wobble follows the `level` prop, so the rings can react to a voice or audio input.
 * - `transfer`: rings are born at the center as calm circles and travel out, gaining wobble, to fade at the edge
 *   (sending, uploading); `direction: "in"` runs them the other way (receiving, downloading).
 * - `stream`: each token sends a small push out from the innermost ring, at uneven gaps set by `rate` (streaming an answer).
 * - `analyze`: a lens of 3–4 rings pulls tight and brightens around one ring, calming inside, and slowly moves
 *   from the innermost ring to the outer and back (deep reading, analysis).
 * - `search`: the wobble grows ring by ring from the center outward, sharpening into tight ripples, then calms
 *   (broad search). Pairs with `decide` for "found".
 */
type NoiseAnimation =
  | "think"
  | "respond"
  | "listen"
  | "ponder"
  | "decide"
  | "voice"
  | "transfer"
  | "stream"
  | "analyze"
  | "search";

const NOISE_ANIMATIONS: NoiseAnimation[] = [
  "think",
  "respond",
  "listen",
  "ponder",
  "decide",
  "voice",
  "transfer",
  "stream",
  "analyze",
  "search",
];

/** Props every noise ring takes. `level` only matters to `voice`, `direction` only to `transfer`, and `rate` only to `stream`. */
interface NoiseSettings {
  level?: number;
  direction?: "out" | "in";
  /** Tokens per second while streaming. */
  rate?: number;
  /** Seconds for one loop of the animation. Think, voice and stream have no loop and ignore it. */
  duration?: number;
  lines: number;
  lineWidth: number;
  amplitude: number;
  frequency: number;
  speed: number;
  spread: number;
  lineSpacing: number;
  size: number;
  color: string;
  minOpacity: number;
  paused: boolean;
}

/** Every number the drawing reads, as the latest props want it. */
function noiseTargets(s: NoiseSettings) {
  return {
    ...colorTargets(s.color),
    lines: Math.min(5, Math.max(1, Math.round(s.lines))),
    lineWidth: s.lineWidth,
    amplitude: s.amplitude,
    frequency: s.frequency,
    speed: s.speed,
    duration: Math.max(0.1, s.duration ?? NOISE_DURATION),
    spread: s.spread,
    lineSpacing: s.lineSpacing,
    minOpacity: s.minOpacity,
    level: Math.min(1, Math.max(0, s.level ?? 0.5)),
    // 0 flows out from the center, 1 flows in from the edge; between, the rings gather in the middle and turn round.
    inward: s.direction === "in" ? 1 : 0,
    // Named apart from the pause `rate` every scene already reads.
    tokens: Math.max(0, s.rate ?? 6),
  };
}

type NoiseKey = keyof ReturnType<typeof noiseTargets>;

/**
 * Seconds (roughly) each target takes to glide to a new value. Color and opacity fade quickly; `level` tracks
 * a live input, so it follows at the same quick pace to smooth raw readings without lagging speech. A switch
 * of `animation` morphs the rings at the blend pace. Geometry, speed and size take the default `SETTLE`.
 */
const noiseSettle: Partial<Record<NoiseKey | MixKey<NoiseAnimation>, number>> = {
  red: FADE_SETTLE,
  green: FADE_SETTLE,
  blue: FADE_SETTLE,
  alpha: FADE_SETTLE,
  minOpacity: FADE_SETTLE,
  level: FADE_SETTLE,
  inward: BLEND_SETTLE,
  mix_think: BLEND_SETTLE,
  mix_respond: BLEND_SETTLE,
  mix_listen: BLEND_SETTLE,
  mix_ponder: BLEND_SETTLE,
  mix_decide: BLEND_SETTLE,
  mix_voice: BLEND_SETTLE,
  mix_transfer: BLEND_SETTLE,
  mix_stream: BLEND_SETTLE,
  mix_analyze: BLEND_SETTLE,
  mix_search: BLEND_SETTLE,
};

/** How much of each animation is on screen. The radii are blended, so a switch morphs the rings. */
type NoiseMotion = Record<NoiseAnimation, number>;

/** Only `name` on screen. */
function soloNoise(name: NoiseAnimation): NoiseMotion {
  const out = {} as NoiseMotion;
  for (const a of NOISE_ANIMATIONS) out[a] = a === name ? 1 : 0;
  return out;
}

/**
 * Raw noise rarely leaves ±0.5; this stretches it so `amplitude` is close to the real swing.
 * The tanh around it is a soft limit, so peaks round off instead of flattening into corners.
 */
const NOISE_GAIN = 2.2;

const TAU = Math.PI * 2;

/** Seconds per loop when no `duration` is passed. Each single component passes its own, which the group also uses. */
const NOISE_DURATION = 4;

/** Most each ring trails the one outside it while swirling, in radians. */
const SWIRL_LAG = 0.2;

/** Where a flowing ring is born, as a share of the outer radius, so it never starts as a dot. */
const FLOW_START = 0.12;

/** Shares of a crossing a flowing ring takes to fade in at its start, and out at its end. */
const FLOW_FADE_IN = 0.2;

const FLOW_FADE_OUT = 0.35;

/**
 * Gaps between streamed tokens, in average gaps: short runs, a few long pauses. It repeats every
 * `STREAM_GAPS.length` tokens, and the gaps average exactly 1, so `rate` stays the true tokens per second.
 */
const STREAM_GAPS = [0.35, 0.5, 0.3, 2.4, 0.9, 0.4, 0.45, 3.2, 1, 0.35, 1.7, 0.45];

/** Seconds a token's push takes to pass through one ring, and to go from the ring before it to this one. */
const STREAM_PUSH = 0.36;

const STREAM_STEP = 0.1;

/** Share of a push spent rising; the rest it spends letting go. */
const STREAM_RISE = 0.3;

/** Rings either side of the focused one the lens reaches; it fades out by this distance, so 3–4 rings are in it. */
const FOCUS_REACH = 2;

/** How far the rings in the lens close up on the focused one (1 = onto it). */
const FOCUS_PULL = 0.6;

/** Shares of a cycle each scattering ring spends growing, holding wild, and calming. The rest it holds calm. */
const SCATTER_GROW = 0.35;

const SCATTER_HOLD = 0.2;

const SCATTER_CALM = 0.3;

// Improved Perlin noise (3D). The quintic fade keeps the field smooth through its
// second derivative, so the rings bend in soft curves with no creases at cell edges.
const perm = (() => {
  const p = Array.from({ length: 256 }, (_, i) => i);
  // Fixed seed so every render (and the server) gets the same field.
  let s = 1337;
  for (let i = 255; i > 0; i--) {
    s = (s * 16807) % 2147483647;
    const j = s % (i + 1);
    [p[i], p[j]] = [p[j], p[i]];
  }
  return Uint8Array.from({ length: 512 }, (_, i) => p[i & 255]);
})();

function fade(t: number) {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

function grad(hash: number, x: number, y: number, z: number) {
  const h = hash & 15;
  const u = h < 8 ? x : y;
  const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
  return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
}

/** Smooth noise in roughly -1..1. */
function noise3(x: number, y: number, z: number) {
  const X = Math.floor(x) & 255;
  const Y = Math.floor(y) & 255;
  const Z = Math.floor(z) & 255;
  x -= Math.floor(x);
  y -= Math.floor(y);
  z -= Math.floor(z);
  const u = fade(x);
  const v = fade(y);
  const w = fade(z);
  const A = perm[X] + Y;
  const AA = perm[A] + Z;
  const AB = perm[A + 1] + Z;
  const B = perm[X + 1] + Y;
  const BA = perm[B] + Z;
  const BB = perm[B + 1] + Z;
  return lerp(
    lerp(
      lerp(grad(perm[AA], x, y, z), grad(perm[BA], x - 1, y, z), u),
      lerp(grad(perm[AB], x, y - 1, z), grad(perm[BB], x - 1, y - 1, z), u),
      v,
    ),
    lerp(
      lerp(grad(perm[AA + 1], x, y, z - 1), grad(perm[BA + 1], x - 1, y, z - 1), u),
      lerp(grad(perm[AB + 1], x, y - 1, z - 1), grad(perm[BB + 1], x - 1, y - 1, z - 1), u),
      v,
    ),
    w,
  );
}

/** 0 → 1 → 0 over the first `width` of each cycle, resting at 0 for the rest. */
function bump(t: number, width: number) {
  const u = (t - Math.floor(t)) / width;
  return u < 1 ? 0.5 - 0.5 * Math.cos(TAU * u) : 0;
}

/** How one animation shapes one ring. Animations are blended by mixing the radii these produce. */
interface Pose {
  /** Share of the ring's normal distance in from the outer ring (1 = evenly spaced, 0 = on the outer ring). */
  spacing: number;
  /** Slice of the noise field the ring reads. */
  z: number;
  /** Share of the full noise swing (0 = a perfect circle). */
  wobble: number;
  /** Turn of the noise field around the center, in radians. */
  turn: number;
  /** Outward push in px, applied evenly all the way round. */
  push: number;
  /** 0 = the ring's resting opacity, 1 = fully opaque. */
  glow: number;
  /** Opacity of the ring before `glow`; by default its place in the stack, outer ring brightest. */
  rest: number;
  /** How much of the ring is drawn at all (0–1): a flowing ring fades away entirely at both ends of its trip. */
  fade: number;
  /** Multiplies `frequency`, so the bumps around the ring get tighter (above 1) or broader. */
  detail: number;
}

/**
 * Concentric rings warped by smooth noise, counted inward from the outer edge. `motion` says how much of each
 * animation is on screen; it is read every frame, so a switch can glide.
 */
function noiseScene<S extends NoiseSettings, K extends string>(
  motion: (v: Values<K | NoiseKey>) => NoiseMotion,
): Scene<S, K | NoiseKey, never> {
  // `time` is the noise drift (paced by `speed`); `loop` counts loops of the animation (paced by `duration`).
  let time = 0;
  let loop = 0;
  // Streaming: tokens sent so far (fractional), seconds since the scene began, and when each recent token went out.
  let sent = 0;
  let clock = 0;
  const tokens: number[] = [];
  let xs = new Float32Array(0);
  let ys = new Float32Array(0);
  let rs = new Float32Array(0);
  const pose: Pose = { spacing: 1, z: 0, wobble: 1, turn: 0, push: 0, glow: 0, rest: 1, fade: 1, detail: 1 };

  return {
    advance(dt, { v }) {
      time += dt * v.speed * v.rate;
      loop += (dt * v.rate) / v.duration;
      // Walk the gap pattern: every whole gap crossed sends one token. Real seconds, not noise time, so `rate` means
      // tokens per second whatever `speed` is.
      clock += dt * v.rate;
      let gap = dt * v.rate * v.tokens;
      while (gap > 0) {
        const index = Math.floor(sent) % STREAM_GAPS.length;
        const left = (Math.floor(sent) + 1 - sent) * STREAM_GAPS[index];
        if (gap < left) {
          sent += gap / STREAM_GAPS[index];
          break;
        }
        gap -= left;
        sent = Math.floor(sent) + 1;
        tokens.push(clock);
      }
      // A push is gone once it has passed the outer ring of the biggest stack.
      while (tokens.length && clock - tokens[0] > STREAM_PUSH + 5 * STREAM_STEP) tokens.shift();
    },
    draw(ctx, { v, size }) {
      const lineWidth = Math.max(0, v.lineWidth);
      const amplitude = Math.max(0, v.amplitude);
      const frequency = v.frequency;
      const spread = v.spread;
      const minOpacity = v.minOpacity;
      // Fractional while gliding: the ring past the whole count fades in or out.
      const count = Math.max(1, v.lines);
      const rings = Math.ceil(count);
      const center = size / 2;
      // Inset by the widest swing so the outer ring is never clipped.
      const outer = Math.max(1, center - amplitude - lineWidth);
      const spacing = Math.max(0, v.lineSpacing);
      // Enough samples that the curve stays smooth at any size.
      const samples = Math.max(64, Math.ceil((2 * Math.PI * center) / 3));
      if (xs.length < samples) {
        xs = new Float32Array(samples);
        ys = new Float32Array(samples);
        rs = new Float32Array(samples);
      }

      const mix = motion(v);
      const weights = NOISE_ANIMATIONS.map((name) => Math.max(0, mix[name]));
      const total = weights.reduce((a, b) => a + b, 0) || 1;

      ctx.strokeStyle = rgb(v);
      ctx.lineWidth = lineWidth;
      ctx.lineJoin = "round";

      // Rings are counted inward from the outer edge, so adding one only touches the innermost.
      for (let j = 0; j < rings; j++) {
        const presence = Math.min(1, count - j);
        const k = Math.max(0, 1 - j / Math.max(1, count - 1)); // 1 = outer, 0 = innermost
        // Rings step inward from the outer edge, `lineSpacing` apart.
        const base = Math.max(1, outer - j * spacing);
        // Inner rings swing less, so the whole field warps like one surface.
        const swing = amplitude * (base / outer);
        // Walking the noise around a circle closes the loop seamlessly; each ring
        // reads a slightly different slice of time so neighbors ripple together.
        const z = time - j * spread;
        const rest = minOpacity + (1 - minOpacity) * k;
        let opacity = 0;
        rs.fill(0, 0, samples);

        for (let a = 0; a < NOISE_ANIMATIONS.length; a++) {
          const w = weights[a] / total;
          if (w <= 0) continue;
          pose.spacing = 1;
          pose.z = z;
          pose.wobble = 1;
          pose.turn = 0;
          pose.push = 0;
          pose.glow = 0;
          pose.rest = rest;
          pose.fade = 1;
          pose.detail = 1;

          switch (NOISE_ANIMATIONS[a]) {
            case "respond": {
              // Counted from the innermost ring, so the push travels outward. Each ring takes 40% of a cycle
              // and starts 12% after the ring inside it, so 3–4 rings are moving at once.
              const pushed = bump(loop - (rings - 1 - j) * 0.12, 0.4);
              pose.wobble = 0.35;
              pose.push = amplitude * 0.65 * pushed;
              pose.glow = pushed;
              break;
            }
            case "listen":
              // The outer ring leads; each ring inward follows a moment later.
              pose.wobble = 0.08 + 0.92 * (0.5 - 0.5 * Math.cos(TAU * (loop - j * 0.05)));
              break;
            case "ponder":
              // The field turns while it changes slowly, so the twist reads. Inner rings fall behind as it winds up,
              // then catch up again, so the lag stays small enough that neighbors never tangle.
              pose.z = time * 0.4 - j * spread;
              // One full turn per loop; the lag winds up and back over two.
              pose.turn = loop * TAU - j * SWIRL_LAG * (0.5 - 0.5 * Math.cos(loop * Math.PI));
              break;
            case "decide": {
              // Hold a moment closed and a moment open: the cosine is clipped at both ends before easing.
              const wave = 0.5 - 0.5 * Math.cos(TAU * (loop - j * 0.04));
              const closed = easeInOutCubic(Math.min(1, Math.max(0, (wave - 0.15) / 0.7)));
              // Merged rings read the same slice of noise, so they land on exactly one line.
              pose.spacing = 1 - closed;
              pose.z = time - j * spread * (1 - closed);
              pose.glow = closed * 0.5;
              break;
            }
            case "voice":
              pose.wobble = v.level;
              break;
            case "transfer": {
              // The ring is the unit: each one is a whole crossing apart ÷ the ring count, so they stay evenly
              // spaced, and travels at a steady pace (linear), since the flow never stops.
              const trip = loop + (rings - 1 - j) / rings;
              const along = trip - Math.floor(trip);
              const out = along + (1 - 2 * along) * v.inward;
              // Born calm at the center, gaining the full wobble by the edge.
              const target = outer * (FLOW_START + (1 - FLOW_START) * out);
              pose.push = target - Math.max(1, outer - j * spacing);
              pose.wobble = out;
              // The ring moves through the stack, so its opacity follows where it is, not which ring it is.
              pose.rest = minOpacity + (1 - minOpacity) * out;
              // Fades in quickly as it appears and out slowly as it leaves, eased out both ways.
              const appear = easeOut(Math.min(1, along / FLOW_FADE_IN));
              const leave = 1 - easeOut(Math.max(0, (along - (1 - FLOW_FADE_OUT)) / FLOW_FADE_OUT));
              pose.fade = appear * leave;
              break;
            }
            case "stream": {
              // Each token's push starts at the innermost ring and reaches the next a step later; at 0.36s through
              // a ring and 0.1s a step, 3–4 rings carry one push at once. Close tokens stack, softly capped at 1.
              let still = 1;
              for (const sentAt of tokens) {
                const u = (clock - sentAt - (rings - 1 - j) * STREAM_STEP) / STREAM_PUSH;
                if (u <= 0 || u >= 1) continue;
                // Snaps out (arriving) and lets go with a long tail (leaving): both ease out.
                const kick = u < STREAM_RISE ? easeOut(u / STREAM_RISE) : 1 - easeOut((u - STREAM_RISE) / (1 - STREAM_RISE));
                still *= 1 - kick * 0.6;
              }
              const pushed = 1 - still;
              pose.wobble = 0.35;
              pose.push = amplitude * 0.5 * pushed;
              pose.glow = pushed;
              break;
            }
            case "analyze": {
              // The lens sits on a ring counted from the innermost, gliding out to the outer ring and back. It is
              // moving on screen, so each leg eases in and out and lingers a moment at either end.
              const leg = loop;
              const there = 1 - Math.abs(1 - 2 * (leg - Math.floor(leg)));
              const at = easeInOutCubic(there) * (rings - 1);
              const near = Math.max(0, 1 - Math.abs(rings - 1 - j - at) / FOCUS_REACH);
              const lens = 0.5 - 0.5 * Math.cos(Math.PI * near);
              // Close up on the focused ring and read its slice of noise, so the rings in the lens bend together.
              const focused = rings - 1 - at;
              const pull = lens * FOCUS_PULL;
              pose.push = (j - focused) * spacing * pull;
              pose.z = time - (j + (focused - j) * pull) * spread;
              pose.wobble = 1 - 0.75 * lens;
              pose.glow = lens * 0.8;
              break;
            }
            case "search": {
              // Counted from the innermost ring, so the wobble travels outward; each ring starts 10% of a cycle after
              // the one inside it and grows over 35%, so 3–4 rings are growing at once. The swell and calm are
              // on-screen morphs, so both ease in and out.
              const u = loop - (rings - 1 - j) * 0.1;
              const phase = u - Math.floor(u);
              const calmFrom = SCATTER_GROW + SCATTER_HOLD;
              const wild =
                phase < SCATTER_GROW
                  ? easeInOut(phase / SCATTER_GROW)
                  : phase < calmFrom
                    ? 1
                    : 1 - easeInOut(Math.min(1, (phase - calmFrom) / SCATTER_CALM));
              // The noise churns faster here, and tightens into more bumps as the ring goes wild.
              pose.z = time * 2 - j * spread;
              pose.wobble = 0.15 + 0.85 * wild;
              pose.detail = 1 + 0.9 * wild;
              pose.glow = wild * 0.3;
              break;
            }
          }

          const r0 = Math.max(1, outer - j * spacing * pose.spacing) + pose.push;
          const amp = swing * pose.wobble;
          for (let i = 0; i < samples; i++) {
            let r = r0;
            if (amp > 0) {
              const t = (i / samples) * TAU - pose.turn;
              const f = frequency * pose.detail;
              r += Math.tanh(noise3(Math.cos(t) * f, Math.sin(t) * f, pose.z) * NOISE_GAIN) * amp;
            }
            rs[i] += r * w;
          }
          opacity += w * pose.fade * (pose.rest + (1 - pose.rest) * Math.min(1, pose.glow));
        }

        for (let i = 0; i < samples; i++) {
          const a = (i / samples) * TAU;
          xs[i] = center + Math.cos(a) * rs[i];
          ys[i] = center + Math.sin(a) * rs[i];
        }

        // Curve through segment midpoints for a stroke with no visible corners.
        ctx.globalAlpha = v.alpha * presence * opacity;
        ctx.beginPath();
        const end = samples - 1;
        ctx.moveTo((xs[end] + xs[0]) / 2, (ys[end] + ys[0]) / 2);
        for (let i = 0; i < samples; i++) {
          const n = (i + 1) % samples;
          ctx.quadraticCurveTo(xs[i], ys[i], (xs[i] + xs[n]) / 2, (ys[i] + ys[n]) / 2);
        }
        ctx.closePath();
        ctx.stroke();
      }
    },
  };
}
